/** A structured, educational learning path that stays within responsible practical guidance. */
data class LifeSkillsTrack(
    val id: String,
    val title: String,
    val description: String,
    val safetyNotice: String,
    val lessons: List<LifeSkillsLesson>,
)

/** A concise but actionable lesson with explanation, a practice plan and private reflection. */
data class LifeSkillsLesson(
    val id: String,
    val day: Int,
    val title: String,
    val overview: String,
    val keyIdeas: List<String>,
    val practiceSteps: List<String>,
    val application: String,
    val reflectionPrompt: String,
    val decision: LessonDecision,
)

/** A non-manipulative response-choice exercise with transparent learning feedback. */
data class LessonDecision(
    val prompt: String,
    val options: List<String>,
    val recommendedIndex: Int,
    val explanation: String,
)

