    /** Returns a life-skills track by its stable identifier. */
    fun track(id: String): LifeSkillsTrack? = tracks.firstOrNull { it.id == id }

    /** Returns a lesson by stable identifier. */
    fun lesson(id: String): Pair<LifeSkillsTrack, LifeSkillsLesson>? = tracks
        .firstNotNullOfOrNull { track -> track.lessons.firstOrNull { it.id == id }?.let { track to it } }
}

/** Builds a track while generating stable lesson identifiers and avoiding repeated boilerplate. */
private class TrackBuilder(
    private val id: String,
    private val title: String,
    private val description: String,
    private val safetyNotice: String,
) {
    private val lessons = mutableListOf<LifeSkillsLesson>()

    fun lesson(
        title: String,
        overview: String,
        keyIdeas: List<String>,
        practiceSteps: List<String>,
        application: String,
        reflectionPrompt: String,
        decision: LessonDecision,
    ): TrackBuilder {
        lessons += LifeSkillsLesson(
            id = "$id-${lessons.size + 1}",
            day = lessons.size + 1,
            title = title,
            overview = overview,
            keyIdeas = keyIdeas,
            practiceSteps = practiceSteps,
            application = application,
            reflectionPrompt = reflectionPrompt,
            decision = decision,
        )
        return this
    }

    fun build(): LifeSkillsTrack = LifeSkillsTrack(id, title, description, safetyNotice, lessons.toList())
}

private fun decision(prompt: String, options: List<String>, recommendedIndex: Int, explanation: String) =
    LessonDecision(prompt, options, recommendedIndex, explanation)
